window.__saqPaperQuestions("2023-1-sa-nt",[{"number":1,"title":"","stemText":"(18 marks) You are the ED consultant in a tertiary hospital with a mixed ED, a 10-year-old boy has been\nhit by a car travelling at 80kph and has arrived in your Resus room.\nPrimary survey notes the following findings: Airway patent","parts":[{"id":"b","label":"Part B","prompt":"Calculate an estimated weight for the patient. (1 mark) 40kg (age x 4) During your primary survey, GCS deteriorates to 7 (E1, V2, M4) and the decision is made to intubate."},{"id":"c","label":"Part C","prompt":"Complete the table including calculations or doses where appropriate. (4 marks) Measurement/medication with Calculation/dose ETT size ETT depth Induction agent Muscle relaxant A Skeletal Trauma Series and eFAST have been performed:"},{"id":"d","label":"Part D","prompt":"List four (4) significant injuries present in this patient and your clinical reasoning for your diagnoses (8 marks) Injury Clinical Reasoning (4 marks) (4 marks) His left pupil has now become dilated, 7mm and unreactive."},{"id":"e","label":"Part E","prompt":"State one (1) medication and the dose that you would give. (1 mark) His abdomen has become distended, and his BP is now 72/50."},{"id":"f","label":"Part F","prompt":"List four (4) transfusion targets, blood products and volumes you would give (assume that ROTEM is unavailable) (4 marks) Blood Product Volume/dose and Transfusion target (4 marks) RBC\n\nPlatelets\nFFP Cryoprecipitate"}],"propPages":["asset:img4ae70c8918ae8b6889","asset:img930353c8b1acdc111a","asset:img645ce7ed421aa67858"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["spine protected using sandbags and tape Right sided abrasions and bruising to face, chest and abdomen with chest wall and abdominal tenderness No obvious evidence of significant external haemorrhage Observations on arrival:\n\nHR\n148 bpm\n\nBP\n82/58 mmHg\n\nRR\nbpm\n\nSats\n91% RA CRT 4secs, peripheries cool and mottled\n\nGCS\n13 (E3, V4, M6)"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>APLS:</strong> Ages 6-12 yrs = (3 x age in years) + 7 = 37kgs</div><div class=\"answer-line\"><strong>OR</strong> Can use for ages 1-10yrs (age +4) x2 = 28kgs</div><div class=\"answer-line\"><strong>OR </strong>Rough estimate for &gt;9yrs: age x3 = 30kgs</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>6cms cuffed (plus ½ size larger</td><td>Cuffed: age/4 + 3.5 = 6cms</td><td></td></tr><tr><td>and smaller)</td><td>Uncuffed: age/4 +4 = 6.5cms</td><td></td></tr><tr><td><strong>ETT depth </strong></td><td>17cms oral</td><td>Oral tube: Age/2 +12</td></tr><tr><td colspan=\"3\">Nasal tube: Age/2 +15 (20 cms)</td></tr><tr><td><strong>Induction agent </strong></td><td>Ketamine</td><td>60mg (1-2mg/kg)</td></tr><tr><td>Thiopentone</td><td>30-150mg (1-5mg/kg)</td><td></td></tr><tr><td>Propofol not 1st choice as</td><td>60mg (2mg/kg)</td><td></td></tr><tr><td colspan=\"3\">hypotensive</td></tr><tr><td><strong>Muscle relaxant </strong></td><td>Rocuronium</td><td>30mg (0.6-1mg/kg)</td></tr><tr><td>Suxamethonium</td><td>60mg (2mg/kg)</td><td></td></tr><tr><td>Vecuronium</td><td>3mg (0.1-0.2mg/kg)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>TBI with ICH</td><td>Decrease in initial GCS 13 to 7</td></tr><tr><td>Multiple pelvic fractures</td><td>Minimally displaced comminuted fracture Rt</td></tr><tr><td>(Need to identify at least the 1st 2)</td><td>inferior pubic ramus</td></tr><tr><td colspan=\"2\">Mildly displaced Lt ischial ramus # (adjacent</td></tr><tr><td colspan=\"2\">to left ischial tuberosity)</td></tr><tr><td colspan=\"2\">Rt ischial ramus #</td></tr><tr><td colspan=\"2\">Cortical step also seen Rt pubic tubercle –</td></tr><tr><td colspan=\"2\">undisplaced #</td></tr><tr><td>Right femoral fracture</td><td>Transverse fracture Rt proximal femoral</td></tr><tr><td colspan=\"2\">shaft</td></tr><tr><td>Pulmonary contusions</td><td>Patchy airspace opacities within right mid to</td></tr><tr><td colspan=\"2\">lower zones. No displaced rib fractures seen</td></tr><tr><td colspan=\"2\">but likely present</td></tr><tr><td>Intra-abdominal injury with FF on e-FAST</td><td>Positive eFAST with FF in Morrison’s Pouch</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">3% NaCl 3mls/kg 90mls OR Mannitol 0.25-1g/kg</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">300-600mls (10-20mL/kg)</div><div class=\"answer-line\">Hb &gt;70g/dL</div><div class=\"answer-line\"><strong>Platelets </strong></div><div class=\"answer-line\">300 – 450mls (10-15ml/kg)</div><div class=\"answer-line\">Plts &gt; 50 x 109/L</div><div class=\"answer-line\"><strong>FFP </strong></div><div class=\"answer-line\">300 – 450mls (10-15ml/kg)</div><div class=\"answer-line\">PT/APTT &lt;1.5 x normal</div><div class=\"answer-line\"><strong>Cryoprecipitate </strong></div><div class=\"answer-line\">150mls (5mls/kg)</div><div class=\"answer-line\">Fibrinogen &gt;2g/L</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(18 marks) You are the tertiary ED Consultant on duty. Your team is treating a 40-year-old male with severe life-threatening asthma. The patient is currently alert, GCS 15. 88% 15L O2, 150/95,\n\nRR 32. You have optimised medical therapy.\nYou consider commencing the patient on NIV.","parts":[{"id":"a","label":"Part A","prompt":"State the benefits of NIV in this setting. (2 marks) After 1 hour, despite maximal therapy and NIV, your patient starts to fatigue. The team and you have decided to intubate the patient."},{"id":"b","label":"Part B","prompt":"Post intubation, describe four (4) of your ventilator settings and explain the rationale for each of your choices. (8 marks) Ventilator setting Rationale (4 marks) (4 marks) 15 minutes post intubation, the patient becomes hypotensive 72/50 mmHg."},{"id":"c","label":"Part C","prompt":"What are the four (4) potential aetiologies and what steps would you take to treat them? (8 marks) Aetiology Treatment (4 marks) (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">NIV has a number of theoretical benefits in asthma:</td></tr><tr><td>•</td><td>Extrinsic PEEP decreases the work of breathing by helping overcome Auto-</td></tr><tr><td colspan=\"2\">PEEP</td></tr><tr><td>•</td><td>Extrinsic inspiratory positive pressure (IPAP) may increase tidal volume by</td></tr><tr><td colspan=\"2\">decreasing the work done against airway resistance</td></tr><tr><td>•</td><td>Shorter inspiratory times may increase tidal volumes without causing any</td></tr><tr><td colspan=\"2\">extra dynamic hyperinflation</td></tr><tr><td>•</td><td>NIV may be able to prevent intubation in a selected group of patients.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>• FiO2 1.0 – newly intubated – titrate down asap as risk of O2 toxicity and Aa</td><td></td></tr><tr><td>gradient not usually a problem</td><td></td></tr><tr><td>•</td><td><strong>Use minimal PEEP</strong>. One usually does not have a work of breathing to</td></tr><tr><td>decrease in the sedated paralysed asthmatic, and so there is no need to</td><td></td></tr><tr><td>overcome Auto-PEEP with intrinsic PEEP. Rather, one should instead make</td><td></td></tr><tr><td>no effort to contribute to the existing Auto-PEEP. However, now it would</td><td></td></tr><tr><td>appear that some small level of PEEP is actually beneficial - the theory is that</td><td></td></tr><tr><td>it splints the spastic bronchi open, and thus actually improves the clearance</td><td></td></tr><tr><td>of CO2 (as those little airways were otherwise going to collapse in</td><td></td></tr><tr><td>expiration).</td><td></td></tr><tr><td>• VT 4-6ml per kg – limited by plateau pressure &lt; 30 – note PIPs will be high</td><td></td></tr><tr><td>and need to be tolerated, e.g. up to 50 cmH2O), ventilator alarms will need</td><td></td></tr><tr><td>to be adjusted</td><td></td></tr><tr><td>• RR / T insp. to be minimised to avoid dynamic hyper-inflation (or prolong</td><td></td></tr><tr><td>exp. time). RR 6-8 acceptable</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Dynamic hyperinflation exacerbating the preload reduction. Treat by</div><div class=\"answer-line\">disconnection of patient from the ventilator and transiently ceasing ventilation.</div><div class=\"answer-line\">Occasionally manual compression of chest required to aid expiration. Prevention</div><div class=\"answer-line\">is with settings targeting lower RR, and shorter insp time, Pplat &lt;30 cmH2O.</div><div class=\"answer-line\">Accepting high pCO2 if necessary.</div><div class=\"answer-line\">• Afterload reduction/obliteration of sympathetic stimulation – drugs (sedatives</div><div class=\"answer-line\">and bronchodilators), use vasoconstrictors (titrated metaraminol or</div><div class=\"answer-line\">noradrenaline)</div><div class=\"answer-line\">• Hypovolemia – unwell by days, inadequate PO intake and then positive</div><div class=\"answer-line\">intrathoracic pressure – decreasing preload further, minimised by IV fluids</div><div class=\"answer-line\">loading prior to intubation, and volume loading afterwards to treat.</div><div class=\"answer-line\">• Tension pneumothorax. treated with immediate decompression.</div><div class=\"answer-line\">• Anaphylaxis to induction drugs– IM Adrenaline</div><div class=\"answer-line\">*If dynamic hyperinflation as a cause of hypotension was not mentioned, a candidate</div><div class=\"answer-line\">could only score a maximum of 4/8</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"(12 marks)\nA 41-year-old female presents to your emergency department with acute onset\nshortness of breath and chest pain. Her past history includes obesity, hypothyroidism, T2DM, and is an active smoker. On arrival to resus her observations are as follows:\n\nRR\nbpm\n\nSaO2 82%\n15L NRB,\n\nHR\n110 bpm\n\nBP\n160/100 mmHg\n\ntemp 37.7 degrees C\nOn examination she is distressed and teary, auscultation of her chest is clear, central\n\ncapillary refill is 4s and she has cool peripheries.","parts":[{"id":"a","label":"Part A","prompt":"Excluding Pulmonary Embolism (PE), list two (2) other differentials for her presentation. (2 marks)"},{"id":"b","label":"Part B","prompt":"Define the following (2 marks) Massive PE: Sub-massive PE:"},{"id":"c","label":"Part C","prompt":"List ECHO findings that may be found in sub massive PE (4 marks)"},{"id":"d","label":"Part D","prompt":"After your assessment you diagnose PE- outline your initial management. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Acute coronary syndrome</div><div class=\"answer-line\">COPD / asthma exacerbation</div><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">Other – pericardial effusion, myocarditis, pleural effusion,</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Massive PE</div><div class=\"answer-line\">i. acute PE with obstructive shock – sBP&lt;90</div><div class=\"answer-line\">Submassive PE</div><div class=\"answer-line\">ii. acute PE without shock but with either RV dysfunction or myocardial</div><div class=\"answer-line\">necrosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">RV wall hypokinesis / McConnel Sign</div><div class=\"answer-line\">RV dilation</div><div class=\"answer-line\">Septal flattening / paradoxical RV septal motion</div><div class=\"answer-line\">Dilated IVC with lack of respiratory collapse / variation</div><div class=\"answer-line\">Intraluminal RH thrombus</div><div class=\"answer-line\">Other – TR, RVF, PHT</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">▪ Oxygenation</div><div class=\"answer-line\">• NHFC with settings</div><div class=\"answer-line\">• NIV with settings and mention of caveat – decrease venous return</div><div class=\"answer-line\">and hypotension.</div><div class=\"answer-line\">• Consider need for intubation</div><div class=\"answer-line\">▪ Circulation</div><div class=\"answer-line\">• IVT – judicious fluid loading</div><div class=\"answer-line\">• Invasive blood pressure monitoring</div><div class=\"answer-line\">• Inotropic / vasopressor support</div><div class=\"answer-line\">o Specific management (1 mark)</div><div class=\"answer-line\">▪ Clexane 1mg/kg BD or 1.5mg daily SC dose <em>OR </em>Heparin load + infusion</div><div class=\"answer-line\">▪ Thrombolysis – drug and dose (not in sub massive unless discussed with</div><div class=\"answer-line\">ICU, respiratory or progression to massive PE)</div><div class=\"answer-line\">o Disposition (1 mark)</div><div class=\"answer-line\">▪ ICU and respiratory consult</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"(12 marks)\nA 15-day old male is referred in by community midwives for ongoing jaundice.\nHe was born at 39 weeks via an elective Caesarean section. He has had jaundice since\nday 2 of life and not required treatment to date.\nHis vital signs are all within range and afebrile.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) possible causes of jaundice in this neonate and one key feature within the history, examination or investigation that will help you diagnose that condition. (8 marks) Cause of Jaundice Key feature (4 marks) (4 marks) After your assessment, no clear cause can be identified. His serum bilirubin level is below the level required for phototherapy."},{"id":"b","label":"Part B","prompt":"List four (4) considerations to enable safe discharge of this child (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Unconjugated (some of the below can manifest with an elevated conjugated component)</td></tr><tr><td>Hypothyroidism (will consider other</td><td>Elevated TSH/ low FT4</td></tr><tr><td>endocrine disorders (hypopit,</td><td>Positive newborn screening test for congenital</td></tr><tr><td>hypoadrenalism)</td><td>hypothyroidism</td></tr><tr><td colspan=\"2\">Familial history</td></tr><tr><td>Haemolysis - G6PD. Others sickle cell,</td><td>Blood – bite/blister cells (G6PD)</td></tr><tr><td>thalassaemia, spherocytosis.</td><td>G6PD assay</td></tr><tr><td colspan=\"2\">Splenomegaly (spherocytosis)</td></tr><tr><td colspan=\"2\">History of fever, poor feeding, elevated WCC, CRP,</td></tr><tr><td>Sepsis</td><td>positive blood culture/LP/urine</td></tr><tr><td>UTI</td><td>Fever, positive micro</td></tr><tr><td>Increased extravascular blood (low on the</td><td>Examination finding of cephalhaematoma. Birth</td></tr><tr><td>list)</td><td>history.</td></tr><tr><td>Polycythaemia</td><td>Elevated haematocrit, small for gestation age</td></tr><tr><td colspan=\"2\">history. Twin-twin transfusion</td></tr><tr><td>Breast milk jaundice</td><td>Diagnosed by exclusion (other that exclusive</td></tr><tr><td colspan=\"2\">breast feeding there are no particular</td></tr><tr><td colspan=\"2\">distinguishing features)</td></tr><tr><td colspan=\"2\">Conjugated</td></tr><tr><td>Biliary atresia</td><td>Acholic stools,Hepatomegaly</td></tr><tr><td colspan=\"2\">Raised conjugated bilirubin (&gt;10-20% of total)</td></tr><tr><td>Metabolic disorders</td><td>Positive newborn screening test</td></tr><tr><td>TORCH infections</td><td>History, positive screen if done</td></tr><tr><td>Drugs (sulphonamides, erythromycin,</td><td>Identified from history</td></tr><tr><td colspan=\"2\">ceftriaxone, ibuprofen)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Term baby</div><div class=\"answer-line\">Clinically well</div><div class=\"answer-line\">Has adequate follow up and bilirubin can be checked again</div><div class=\"answer-line\">Feeding adequate</div><div class=\"answer-line\">Social determinants – mother well supported, social concerns</div><div class=\"answer-line\">Discharge plan with a good safety net with regards to poor feeding, irritability, fever etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"(12 marks)\nA 30-year-old female has been brought into your tertiary Emergency Department following\na brief syncope episode while running a marathon.","parts":[{"id":"a","label":"Part A","prompt":"Besides chest pain and palpitations, list four (4) other historical features which would suggest a cardiac cause of syncope. (4 marks)\nA 12 lead ECG is performed as below."},{"id":"b","label":"Part B","prompt":"Analyse the ECG. (2 marks)"},{"id":"c","label":"Part C","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"d","label":"Part D","prompt":"List three (3) clinical examination findings which are associated with the condition above. (3 marks)"},{"id":"e","label":"Part E","prompt":"What are two (2) complications that may arise with the condition as stated above. (2 marks)"}],"propPages":["asset:imgd3fee7885f850a0e26"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">family history of arrhythmia, older population, male</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">mimicking inferior or lateral MI, tall R waves in in leads V1 – V2 that mimic PMI or</div><div class=\"answer-line\">RVH</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">d) Sharp jerky pulse, double/triple apical pulses, prominent a wave on JVP due to</div><div class=\"answer-line\">decreased RV compliance, systolic ejection murmur, S2 may be paradoxically split</div><div class=\"answer-line\">due to high LVOT gradient</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">decreased RV compliance, systolic ejection murmur, S2 may be paradoxically split</div><div class=\"answer-line\">due to high LVOT gradient</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">mural thrombus, sudden death, SVT with pre excitation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"(12 marks) You are the morning consultant, and an alarm bell goes off for your Short Stay area.\nOn arrival you find a 38-year-old female having a tonic-clonic seizure.","parts":[{"id":"a","label":"Part A","prompt":"State six (6) steps in your immediate actions. (6 marks) The patient remains seizing at 5 minutes despite your initial actions."},{"id":"b","label":"Part B","prompt":"Complete the following table for second line antiepileptic medications. (6 marks) Loading dose, max dose, and Contra-indication Medication rate of administration (3 marks) (3 marks) Levetiracetam Sodium valproate Phenytoin"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ensure patient positioning to not harm self or others</div><div class=\"answer-line\">Maintain patent airway, apply oxygen, obtain saturations and monitoring</div><div class=\"answer-line\">Draw up midazolam 5-10mg, if still seizing at 3-5 minutes, give IV or IM</div><div class=\"answer-line\">Take blood for BSL, BHCG, Na and VBG</div><div class=\"answer-line\">Move to resus / acute area for further treatment</div><div class=\"answer-line\">Obtain collateral from staff around presentation, background, and treatment</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>Levetiracetam </strong></td><td>60mg/kg up to 4.5g, over 10</td><td>Allergy / None</td></tr><tr><td colspan=\"3\">min</td></tr><tr><td><strong>Sodium valproate </strong></td><td>40mg/kg up to 3gm, over 5-10</td><td>Pregnancy</td></tr><tr><td colspan=\"3\">minutes</td></tr><tr><td><strong>Phenytoin </strong></td><td>20mg/kg, max 1.5gm, max rate</td><td>Pregnancy, hypotension,</td></tr><tr><td>50mg / min</td><td>toxicological seizures</td><td></td></tr><tr><td colspan=\"3\">Accept 2nd dose of benzodiazepines – midazolam, 5-10mg, 2nd dose must be IV, slow push</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(12 marks) You are the single doctor working in a rural facility 150km from the tertiary referral centre.\nA 25-year-old male presents to your ED with severe lower leg pain which has developed\ntoday. He can mobilise on the leg and cannot recall any recent trauma, although was riding a jet ski on the sea the day prior to presentation. He is an insulin dependent diabetic. The nursing staff assess the patient prior to your review. They report he is febrile, with\na heart rate of 110/ min, and a blood pressure of 100/ 70. There are no visible wounds\n• n his leg and an x-ray does not show any bony injury.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) differential diagnoses that you are considering as you begin your examination of this patient. (3 marks)"},{"id":"b","label":"Part B","prompt":"List three (3) further examination features that would assist in your differential diagnosis. (3 marks)"},{"id":"c","label":"Part C","prompt":"State the three (3) most important management priorities- along with justified reason or detail. (6 marks) Management priority Justification/ detail (3 marks) (3 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Necrotizing fasciitis</div><div class=\"answer-line\">Cellulitis</div><div class=\"answer-line\">Anything else reasonable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Oedema that extends beyond the visible erythema</div><div class=\"answer-line\">Erythema without sharp margins</div><div class=\"answer-line\">Crepitus</div><div class=\"answer-line\">Cutaneous anaesthesia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Antibiotics</td><td>IV Meropenem 1g (or Pip-Taz 4.5g)</td></tr><tr><td colspan=\"2\">IV Vancomycin 25-30mg/ kg</td></tr><tr><td colspan=\"2\">IV Clindamycin 600mg</td></tr><tr><td colspan=\"2\">IV Ciprofloxacin 400mg (to cover water</td></tr><tr><td colspan=\"2\">exposure)</td></tr><tr><td>Organise transfer to tertiary centre with</td><td>Likely via retrieval following discussion with</td></tr><tr><td>surgical facilities</td><td>surgeon as requires urgent surgical</td></tr><tr><td colspan=\"2\">debridement, high risk of further</td></tr><tr><td colspan=\"2\">deterioration en route</td></tr><tr><td>Fluid resuscitation</td><td>NS or Hartmanns 15-30ml/ kg the</td></tr><tr><td colspan=\"2\">consideration of inotropic support, aiming</td></tr><tr><td colspan=\"2\">for MAP 65</td></tr><tr><td>Analgesia</td><td>IV analgesia</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"(12 marks)\nA 64-year-old male cyclist was struck by a train at crossing at approximately 50km/hr.\nHis GCS was 3 at scene and was brought into your tertiary emergency department at 1800\nby the Ambulance Service. He has significant right periorbital bruising with some blood in his airway with epistaxis. His initial observations are:\nSp02 88% 15L NRB\n\nHR\n130 bpm\n\nBP\n90/60 mmHg\n\nRR\nbpm A CT scan has been ordered.","parts":[{"id":"a","label":"Part A","prompt":"What is your initial management of this patient? (4 marks) This space is intentionally blank Images of the CT are shown below:"},{"id":"b","label":"Part B","prompt":"Analyse the CT images- listing four (4) positive findings. (4 marks) The patient’s right intraocular pressure is 50 and you are concerned about orbital compartment syndrome. You decide you will need to perform a right lateral canthotomy."},{"id":"c","label":"Part C","prompt":"List two (2) complications of lateral canthotomy- excluding bleeding, pain, and infection? (2 marks) Post intubation, your patient has an unstable midface with ongoing oropharyngeal haemorrhage that continues despite correcting the patient’s underlying coagulopathy."},{"id":"d","label":"Part D","prompt":"What other strategies can you employ? (2 marks) This space is intentionally blank"}],"propPages":["asset:img414df9e852733b1a18","asset:imgc8c70b8a97b9496b1d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hypotensive – optimising blood pressure with concerns of head injury – commence</div><div class=\"answer-line\">packed red cells, aiming for balanced ratio of 1:1:1 with massive transfusion protocol</div><div class=\"answer-line\">ordered with ROTEM guided haemostatic resuscitation.</div><div class=\"answer-line\">Bleeding – Tranxenamic acid 1g IV, direct packing of oral bleed; application of rapid rhino/</div><div class=\"answer-line\">epistat to stop epistaxis</div><div class=\"answer-line\">Difficult airway - Modified RSI with double suction ready, neck marked for front of neck</div><div class=\"answer-line\">access if required as part of airway plan, intubation with ketamine 30mg and rocuronium</div><div class=\"answer-line\">150mg IV. If available, awake fibreoptic intubation.</div><div class=\"answer-line\">Securing airway with manual inline stabilisation, maintaining c-spine precautions</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Tripod fracture of the right zygomaticomaxillary complex. Blood in maxillary sinus</div><div class=\"answer-line\">Blow out fracture right orbital floor with fat entrapment</div><div class=\"answer-line\">Significant subcutaneous emphysema within orbit.</div><div class=\"answer-line\">Left comminuted maxillary sinus fractures.</div><div class=\"answer-line\">Fractured left orbital floor</div><div class=\"answer-line\">Blood in paranasal sinuses</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Injury to the globe and aperture of the eye</div><div class=\"answer-line\">Interruption of lacrimal gland</div><div class=\"answer-line\">Injury to lateral rectus muscle</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Dental bite blocks</div><div class=\"answer-line\">C-spine collar to brace the mandible</div><div class=\"answer-line\">**The mandible is stabilised on top of the semi-rigid cervical collar; the hard palate is held in</div><div class=\"answer-line\">place against stable mandible by the bite blocks; maxilla fixed in position by the epistats</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"As a new consultant you have noticed an increased use of US for PIV insertion within your ED. You have also noted that techniques vary widely and want to standardise the practice to ensure competence in your staff and safety for patients. To do this, you’ve decided to develop a guideline for US guided PIV insertion for use in your ED.","parts":[{"id":"a","label":"Part A","prompt":"Give four (4) considerations to feasibility of implementing this guideline. (4 marks)"},{"id":"b","label":"Part B","prompt":"List three (3) resources you could use to develop a guideline such as this. (3 marks)"},{"id":"c","label":"Part C","prompt":"Give three (3) steps you would take to implement the new guideline in your ED. (3 marks)"},{"id":"d","label":"Part D","prompt":"Name two (2) ways you would assess the success of your new guideline and ensure its development. (2 marks) SA/NT TRIAL EXAM SAQ 2023.1\nBOOKLET 2\n(SAQs 10-18)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cost</div><div class=\"answer-line\">Equipment/material availability</div><div class=\"answer-line\">Staff Expertise</div><div class=\"answer-line\">Need/usefulness</div><div class=\"answer-line\">Interest/acceptance</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Primary literature</div><div class=\"answer-line\">Meta-analysis</div><div class=\"answer-line\">Existing specialty guidelines (ACEM, RANZCR, RACS/ANZSVS)</div><div class=\"answer-line\">Expert opinion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Dissemination of the guideline for input</div><div class=\"answer-line\">Education on performing the procedure/guideline</div><div class=\"answer-line\">Trial period for fine-tuning the guideline</div><div class=\"answer-line\">Ensuring materials/equipment were available and accessible</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Audit outcomes</div><div class=\"answer-line\">Fixed dates for review/updating guideline</div><div class=\"answer-line\"><strong>Booklet 2 </strong></div><div class=\"answer-line\"><strong>Answers  </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"(18 marks) Your resident asks for your advice after they have reviewed a 10-month-old infant who has presented to your ED multiple times this year. They are concerned about non-accidental injury. They are seeking your reassurance that their suspicions are reasonable.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) features in the history that would make you suspect physical abuse or inflicted injury. (4 marks)"},{"id":"b","label":"Part B","prompt":"List six (6) specific findings regarding bruising that increase your suspicion for inflicted injury. (6 marks)"},{"id":"c","label":"Part C","prompt":"Other than those related to bruising, list two (2) physical examination findings that are HIGHLY specific for inflicted injury. (2 marks) The infant has presented with a limp- developmentally they are described as “cruising using furniture”. The X-Ray of the lower limb is shown below."},{"id":"d","label":"Part D","prompt":"Describe the findings on the X-ray and provide the significance of this finding. (2 marks) XR findings Significance"},{"id":"e","label":"Part E","prompt":"Other than the findings described in the previous answer list four (4) radiographic features that are highly specific for non-accidental injuries or inflicted injuries. (4 marks)"}],"propPages":["asset:img5c0ec12409ff9597d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">injury not c/w development</div><div class=\"answer-line\">injury and history given are inconsistent</div><div class=\"answer-line\">delayed presentations</div><div class=\"answer-line\">h/o multiple fractures with no family history of osteogenesis imperfecta</div><div class=\"answer-line\">multiple presentations</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Children who are not mobile should not have ANY unexplained bruises.</div><div class=\"answer-line\">Symmetrical bruising</div><div class=\"answer-line\">Torso, ear, or neck bruising in any child</div><div class=\"answer-line\">Patterned bruising, especially hand prints</div><div class=\"answer-line\">Soft tissue bruising: buttocks, abdomen</div><div class=\"answer-line\">Bruises in different stages of healing</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">retinal haemorrhage</div><div class=\"answer-line\">torn frenulum</div><div class=\"answer-line\">other egs (palpable calluses, specific shaped burns eg cigarette lighter)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Metaphyseal fractures: corner fracture of the distal femur and bucket handle fracture of the</div><div class=\"answer-line\">proximal tibia</div><div class=\"answer-line\">Considered virtually pathognomonic of NAI</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Multiple fractures of varying ages</div><div class=\"answer-line\">Posterior rib fractures</div><div class=\"answer-line\">Non parietal skull fracture</div><div class=\"answer-line\">Scapula fractures</div><div class=\"answer-line\">Sternal fractures</div><div class=\"answer-line\">outer third clavicular fractures</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"(18 marks)\nA 72-year-old man is brought to the Emergency Department by ambulance as a Code\nStroke with headache and left sided facial droop.","parts":[{"id":"a","label":"Part A","prompt":"Provide FIVE (5) alternative diagnoses or stroke mimics that this patient may have and the clinical features that would distinguish them from an acute stroke. (10 marks) Stroke Mimic Distinguishing Clinical Features (5marks) (5 marks) A CT brain with perfusion scan is undertaken which confirms he has had an ischaemic stroke with a blockage involving a branch of the right middle cerebral artery. Intracranial haemorrhage and aortic dissection have been excluded. Consideration is being given to thrombolysis."},{"id":"b","label":"Part B","prompt":"List THREE (3) absolute contraindications and TWO (2) relative contraindications to thrombolysis in this patient. (5 marks) Absolute contraindications (3 marks) Relative contraindications (2 marks) The patient undergoes thrombolysis, and their symptoms resolve within 3 hours."},{"id":"c","label":"Part C","prompt":"In patients sustaining an acute stroke, state three (3) factors which are associated with a poor prognosis or outcome. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Sub arachnoid Haemorrhage</td><td>Sudden onset severe headache.</td></tr><tr><td>Seizures/post ictal paralysis</td><td>Paralysis following a seizure. Is usually transient.</td></tr><tr><td colspan=\"2\">(Todd paralysis)</td></tr><tr><td>Brain Neoplasm</td><td>Gradual onset of symptoms. May be accompanied by other signs</td></tr><tr><td colspan=\"2\">and symptoms of raised intracranial pressure.</td></tr><tr><td>Brain abscess</td><td>Gradual onset. History of fever. Risk factors such as intravenous</td></tr><tr><td colspan=\"2\">drug use</td></tr><tr><td>Hypertensive Encephalopathy</td><td>Hypertension. Often associated with visual symptoms. Delirium</td></tr><tr><td colspan=\"2\">may be present. Other signs and symptoms of cerebral oedema.</td></tr><tr><td>Meningitis/encephalitis</td><td>Fever. Often associated with photophobia and neck stiffness.</td></tr><tr><td>Bell’s Palsy</td><td>Sparing of forehead muscle movement. Younger age. Preceding</td></tr><tr><td colspan=\"2\">viral illness</td></tr><tr><td>Complicated Migraine</td><td>Preceding aura. Previous history of migraines. Younger age.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Absolute 1): Systolic BP &gt;185mmHg or Diastolic BP &gt;110mmHg despite treatment.</div><div class=\"answer-line\">Absolute 2): Known coagulopathy (heredity or acquired)</div><div class=\"answer-line\">-INR &gt;1.7</div><div class=\"answer-line\">-Therapeutic anticoagulant (DOAC) exposure &lt;12hrs</div><div class=\"answer-line\">-Recent Heparin with raised APTT</div><div class=\"answer-line\">-Platelet count &lt;100,000/ µL</div><div class=\"answer-line\">Absolute 3): Seizure at symptom onset with no CTP lesion</div><div class=\"answer-line\">Absolute 4): Blood Glucose &lt;3.5 or &gt; 22mmol/L with no CTP lesion.</div><div class=\"answer-line\">Relative 1): age &lt;18 years</div><div class=\"answer-line\">Relative 2): pregnancy</div><div class=\"answer-line\">Relative 3): Minor non-disabling stroke (e.g., Sensory deficit)</div><div class=\"answer-line\">Relative 4): CT evidence of extensive middle cerebral artery territory infarction(&gt;1/3 MCA)</div><div class=\"answer-line\">Relative 5): Stroke or serious head injury in the last 3 months</div><div class=\"answer-line\">Relative 6): Major Surgery &lt; 14 days</div><div class=\"answer-line\">Relative 7): Severe Comorbidities limiting life expectancy (including pre-existing dementia or</div><div class=\"answer-line\">dependency) or posing treatment risk.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Large vessel occlusion</div><div class=\"answer-line\">Presence of atrial fibrillation</div><div class=\"answer-line\">No collateral vessels present (form during non-critical ischaemic events)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"(12 marks) A 15-year-old boy presents to the ED with a 3-day history of fever and painful swollen left eye, as shown below.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) abnormalities that are present in this photo of his left eye. (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"List three (3) other signs you will look for in the physical examination of the eye. (3 marks)"},{"id":"d","label":"Part D","prompt":"What is the most common predisposing factor to the condition above? (1 mark)"},{"id":"e","label":"Part E","prompt":"State four (4) complications of this condition. (4 marks) This space is intentionally blank"}],"propPages":["asset:imgb1a7fc898a1e812e92"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Periorbital / lid erythema</div><div class=\"answer-line\">Conjunctival injection / chemosis</div><div class=\"answer-line\">Purulent discharge</div><div class=\"answer-line\">Dilated pupil</div><div class=\"answer-line\">Proptosis</div><div class=\"answer-line\">(b)</div><div class=\"answer-line\">Orbital cellulitis (post-septal)</div><div class=\"answer-line\">(c)</div><div class=\"answer-line\">Ophthalmoplegia / limited extraocular movements</div><div class=\"answer-line\">Decreased visual acuity</div><div class=\"answer-line\">Abnormal pupillary response / RAPD</div><div class=\"answer-line\">Papilloedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Sinusitis (especially ethmoid)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Visual loss</div><div class=\"answer-line\">Orbital abscess</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Sinusitis (especially ethmoid)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Visual loss</div><div class=\"answer-line\">Orbital abscess</div><div class=\"answer-line\">Cerebral venous sinus thrombosis</div><div class=\"answer-line\">Subdural empyema</div><div class=\"answer-line\">Meningitis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"(12 marks) You are reviewing the case of a 55-year-old woman who presented overnight to your rural ED with undifferentiated abdominal pain and vomiting. She has a history of\nhypertension and type 2 diabetes mellitus. She was assessed by a locum medical\n• fficer.\nHer initial VBG showed:\n\npH\n7.29 (7.35-7.45)\n\nHCO3\n14mmol/L 20-28 mmol/L\n\npCO2\n28mmol/L 35-45 mmol/L\n\nNa\n150 mmol/L 135-145mmol/L\n\nK\n5.2 mmol/L 3.5-4.5 mmol/L\n\nCl\n110 mmol/L 100-115 mmol/L\n\nLac\n2.0 mmol/L <2mmol/L Glu 6.2 mmol/L 4-11 mmol/L","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table by performing the necessary calculations. (3 marks) Anion Gap Delta Ratio Expected CO2 Bloods and ECG were non-diagnostic, radiology was not available out-of-hours, and she was admitted overnight to the surgical ward for analgesia and consideration of imaging in the morning. On the ward her clinical picture deteriorated. Ketones were checked at this stage were found to be significantly elevated."},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"Which medication class is MOST associated with this condition? (1 marks) The surgical team the patient was admitted under has asked you to investigate how this error in diagnosis occurred."},{"id":"d","label":"Part D","prompt":"Complete the following table regarding the systems factors that could have been involved in this patient safety event. (3 marks) System factors Examples (3 marks) Clinician Factors Work environment Organisation factors After investigation, it was clear that this was an adverse event that required open disclosure to the patient and their family."},{"id":"e","label":"Part E","prompt":"List four (4) important topical components of the conversation with the patient. (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">AG=150-14-110=26 =&gt;HAGMA  must provide</div><div class=\"answer-line\"><strong>Delta Ratio </strong></div><div class=\"answer-line\">Delta Ratio=(26-12)/(24-16)= 1.4 =&gt;Isolated HAGMA</div><div class=\"answer-line\"><strong>Expected CO2 </strong></div><div class=\"answer-line\">Expected CO2=1.5x14+8 = 29 =&gt; Expected respiratory compensation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Euglycaemic DKA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">SGLT2 inhibitors (half mark for individual drug names: canagliflozin, dapagliflozin, and</div><div class=\"answer-line\">empagliflozin)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Reliance/credentialing/ orientation of locum doctors.</div><div class=\"answer-line\">staff supervision</div><div class=\"answer-line\">education and training</div><div class=\"answer-line\">staff operating outside their role delineation</div><div class=\"answer-line\"><strong>Work environment </strong></div><div class=\"answer-line\">UNAVAILABILITY OF OUT OF HOURS IMAGING</div><div class=\"answer-line\">work load</div><div class=\"answer-line\">work conditions e.g. night shift</div><div class=\"answer-line\"><strong>Organisation </strong></div><div class=\"answer-line\">LACK OF INPATIENT surgical review out of hours</div><div class=\"answer-line\"><strong>factors </strong></div><div class=\"answer-line\">consultation process e.g. telephone advice from inpatient registrar</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><strong>Apology</strong> (or expression of regret) including the words ‘I am sorry’</div><div class=\"answer-line\"><strong>Factual explanation</strong> of what happened, and discuss ongoing care (Keep explanation factual-</div><div class=\"answer-line\">avoid speculative comments, do not make excuses)</div><div class=\"answer-line\">Ensure it is a <strong>2 way conversation</strong></div><div class=\"answer-line\">Explanation of the steps being taken to manage the adverse event and prevent recurrence</div><div class=\"answer-line\">(or <strong>explain process of clinical review and agree to provide feedback</strong>)</div><div class=\"answer-line\">Resources:</div><div class=\"answer-line\">Dunn, Robert et al.  2023,  The emergency medicine manual , Online Textbook, accessed</div><div class=\"answer-line\">07/12/23</div><div class=\"answer-line\">Mathew DS et al, Management of Euglycemic Diabetic Ketoacidosis, US Pharm.</div><div class=\"answer-line\">2021;46(11):HS1-HS6.</div><div class=\"answer-line\">Disclosure-Framework-Feb-2014.pdf</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"(12 marks)\nA 25-year-old woman is brought to the Emergency Department by her father. He reports\nthat she has been feeling unwell with joint pain, abdominal pain, headache, and a rash. She and her family have returned from Bali 3 days ago after a holiday.\nHer observations are as follows:\n\nHR\n110 bpm\n\nBP\n110/70mmHg\n\nRR\nbpm\n\nSpO2 96%\nRA\n\nTemp 39.6 degrees Celsius\n\nGCS\nE 3 V 4 M 6","parts":[{"id":"a","label":"Part A","prompt":"For this patient list two (2) features on history and two (2) features on examination you would assess given the scenario and provide one justification for each. (8 marks) FEATURES ON HISTORY JUSTIFICATION FOR ASSESSING (2 marks) (2 marks) FEATURES ON EXAMINATION JUSTIFICATION FOR ASSESSING (2 marks) (2 marks)"},{"id":"b","label":"Part B","prompt":"In a patient with dengue fever state four (4) criteria that would necessitate inpatient admission. (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Nature of rash – blanching vs non</td><td>Petechial rash concerning</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">infectious diseases such as dengue/ EBV</div><div class=\"answer-line\">Features of meningism – neck stiffness/</div><div class=\"answer-line\">Clinically concerning for meningitis</div><div class=\"answer-line\">Photophobia</div><div class=\"answer-line\">b.</div><div class=\"answer-line\">Evidence of bleeding – eg mucosal bleeding</div><div class=\"answer-line\">Severe abdominal pain</div><div class=\"answer-line\">Severe thrombocytopaenia</div><div class=\"answer-line\">Presence of comorbidities eg immunosuppression/ pregnancy that increase risk of</div><div class=\"answer-line\">severe disease</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"(12 marks) A 14-year-old boy was brought in by his mother, who he lives with. He has been refusing to go to school for the last few days. Today at school, he was verbally aggressive and punched a wall before running home. His mother is concerned that he doesn’t seem to be his normal self.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) classes of pathology, with an example of each, that could cause his acute behavioural disturbance. (3 marks) The patient seems to be agitated and you plan to attempt to de-escalate his behaviour."},{"id":"b","label":"Part B","prompt":"List five (5) important strategies in you communication and approach to this child. (5 marks) The patient becomes more aggressive despite verbal de-escalation, and you are concerned of his safety. He refuses your offer of oral sedation."},{"id":"c","label":"Part C","prompt":"List four (4) PARENTERAL options for pharmacological management- including doses as well. (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Medical condition including: encephalitis, post-ictal period, glucose and electrolyte</div><div class=\"answer-line\">disturbances, pain.</div><div class=\"answer-line\">Drug intoxication or withdrawal including: alcohol, prescription medications, cannabis,</div><div class=\"answer-line\">amphetamines, hallucinogens.</div><div class=\"answer-line\">Mental health conditions including: psychotic disorders, mania, anxiety disorders,</div><div class=\"answer-line\">borderline and anti-social personality disorders.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Listen and talk simply and in a calm manner</td></tr><tr><td>•</td><td>Respect personal space</td></tr><tr><td>•</td><td>Consider child&#x27;s individual needs including language, cognitive ability or trauma</td></tr><tr><td colspan=\"2\">history</td></tr><tr><td>•</td><td>Consider the use, where appropriate, of:</td></tr><tr><td colspan=\"2\">o age-appropriate distraction techniques, familiar toys and objects</td></tr><tr><td colspan=\"2\">o offers of food, drink, icy-pole, or attention to physical needs</td></tr><tr><td>•</td><td>Offer planned &#x27;collaborative&#x27; sedation (eg ask the child if they would take some oral</td></tr><tr><td colspan=\"2\">medication)</td></tr><tr><td>•</td><td>Private/ calming space: quiet room, soft/decreased lighting, eliminate triggers for</td></tr><tr><td colspan=\"2\">agitation</td></tr><tr><td>•</td><td>Safety: remove weapons, obstacles; be aware of exit to avoid further escalation and</td></tr><tr><td colspan=\"2\">ensure your own safety</td></tr><tr><td>•</td><td>Crisis prevention: anticipate and identify early irritable behaviour, consider past</td></tr><tr><td colspan=\"2\">history and involve mental health expertise early for assistance if appropriate</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Droperidol IM 0.1-0.2 mg/kg (max 10 mg)</div><div class=\"answer-line\">Olanzapine IM &lt;40kg – 5 mg, &gt;40 kg –10 mg</div><div class=\"answer-line\">Midazolam IM 0.1-0.2mg/kg (max 20 mg in 24 hours)</div><div class=\"answer-line\">Ketamine IM 4mg/kg (max 400mg)</div><div class=\"answer-line\">00732.pdf</div><div class=\"answer-line\">ute_management/</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"(12 marks)\nA 32-year-old female presents with mild RUQ pain, lethargy, and recurrent vomiting.\nShe has been unwell for 7 days and appears mildly confused.\nShe has no significant past medical history, has never drank alcohol and denies any current medications.\nHer observations are as follows:\n\nPR\n120 bpm\n\nBP\n80/56 mmHg\n\nTemp\n37.7 degrees Celsius\n\nRR\nbpm\n\nSaO2\n95% RA\n\nWCC\n14.4\n\nNa\n130\n\nHb\n103\n\nK\n2.6 Plt 109 Ur 12.1 Bil 103\n\nCr\n190 ALP 190 PO4 0.3 ALT 5239 CCa 2.10 AST 6759 Mg 0.7 GGT 220\n\nINR\n1.6 Urine BHCG Neg","parts":[{"id":"a","label":"Part A","prompt":"List five (5) possible causes for her presentation. (5 marks) The aetiology of her metabolic derangement remains unclear after clinical assessment. Liver screening bloods, an abdominal ultrasound and head, chest and abdominal CT have been\n• rdered. She has had 2L of NaCl 0.9% and her observations remain unchanged"},{"id":"b","label":"Part B","prompt":"List seven (7) of your immediate management priorities. (7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Concealed paracetamol overdose</div><div class=\"answer-line\">Ischaemic Hepatitis due to sepsis/drug overdose</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Viral Hepatitis (A,B,E, EBV, CM, HSV)</div><div class=\"answer-line\">*Note Hep C alone does not cause “acute” hepatitis but can when Hep B/C coinfected.</div><div class=\"answer-line\">Autoimmune Hepatitis</div><div class=\"answer-line\">Budd Chiari/Veno Occlusive disease</div><div class=\"answer-line\">Wilsons disease</div><div class=\"answer-line\">b.</div><div class=\"answer-line\"><strong>Commence inotopic support with Noradrenaline (or alternative appropriate agent such </strong></div><div class=\"answer-line\"><strong>as dopamine/vasopressin) titrating to a MAP of 75 to maintain cerebral and renal </strong></div><div class=\"answer-line\"><strong>perfusion </strong></div><div class=\"answer-line\"><strong>Monitor glucose and correct hypoglycaemia with 50% dextrose boluses/10% dextrose </strong></div><div class=\"answer-line\"><strong>infusion </strong></div><div class=\"answer-line\"><strong>Commence Nac infusion  </strong></div><div class=\"answer-line\"><strong>Broad spectrum antibiotics to cover potential sepsis per eTG – Fluclox 2g and Gentamycin </strong></div><div class=\"answer-line\"><strong>5mg/kg and Vancomycin 25mg/kg </strong></div><div class=\"answer-line\">Correct electrolytes with cardiac monitoring – KCL 10mmol/hr and Phosphate replacement</div><div class=\"answer-line\">over 12 hrs</div><div class=\"answer-line\">Stress ulcer prophylaxis with PPI (high risk of GIT bleeding)</div><div class=\"answer-line\">Head elevation, strict fluid balance and low stimulus environment to prevent ICP rises in</div><div class=\"answer-line\">context of hepatic encephalopathy</div><div class=\"answer-line\">Urgent discussion with nearest liver transplant service and ICU</div><div class=\"answer-line\">Urgent involvement of dietician for nutritional support</div><div class=\"answer-line\">Note: routine correction of coagulopathy is not recommended unless there is active bleeding or the need for</div><div class=\"answer-line\">an invasive procedure. Vit K is only given if a nutritional deficiency or prolonged cholestasis is suspected.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"(12 marks)\nA 27-year-old male has presented to the Emergency Department complaining of\nsevere pain in his right hand involving the palmar aspect, plus his thumb, index and middle fingers. He stated that he was cleaning the façade of a building 12 hours earlier and accidentally splashed his right hand with cleaning solution containing concentrated hydrofluoric acid (HF acid). He said that he washed his hand with soap and water shortly after the incident occurred, under the direction of his supervisor. He is usually fit and well, takes no regular medications, smokes 15 cigarettes per day and is right hand dominant.","parts":[{"id":"a","label":"Part A","prompt":"What are two (2) potential features of topical exposure to hydrofluoric (HF) acid? (2 marks)"},{"id":"b","label":"Part B","prompt":"Why are local anaesthetic techniques contraindicated for pain relief in HF acid injuries? (1 mark)"},{"id":"c","label":"Part C","prompt":"List two (2) most relevant investigations you would perform- with rationale. (4 marks) Investigation Rationale (2marks) (2 marks) The patient received sufficient decontamination pre-hospital and has now received appropriate doses of paracetamol and oxycodone. Despite this he is still in severe pain."},{"id":"d","label":"Part D","prompt":"What specific agent is the antidote for HF acid injury? (1 mark)"},{"id":"e","label":"Part E","prompt":"Provide four (4) ways in which this agent can be administered to treat HF acid injuries. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">May cause systemic hypocalcaemia</div><div class=\"answer-line\">Pain may be delayed and disproportionate to external signs</div><div class=\"answer-line\">Skin changes such as blistering, erythema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">May mask ongoing symptoms - pain is a useful indicator of treatment endpoints</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Electrolytes </em></div><div class=\"answer-line\"><em>To </em></div><div class=\"answer-line\"><em>exclude </em></div><div class=\"answer-line\"><em>hypocalcaemia, </em></div><div class=\"answer-line\"><em>hypomagnesaemia, hypo/er kalaemia </em></div><div class=\"answer-line\"><em>ECG </em></div><div class=\"answer-line\"><em>Prolonged QT as marker of hypocalcaemia </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Calcium Gluconate</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><em>10mLof 10%  calcium gluconate injection in 30mL of lubricant gel.  </em></div><div class=\"answer-line\"><em>Place gel in glove and patient’s hand in glove</em></div><div class=\"answer-line\"><em>Calcium gluconate subcutaneous/intradermal injection for hand NOT fingers </em></div><div class=\"answer-line\"><em>Infiltrate 0.5mL of 5% calcium gluconate per square cm of affected skin </em></div><div class=\"answer-line\"><em>Beware compartment syndrome</em></div><div class=\"answer-line\">Biers block technique (1g calcium gluconate in 40mL 0.9% saline) IV, release cuff after 20</div><div class=\"answer-line\">mins</div><div class=\"answer-line\"><em>Intra-arterial infusion (1g calcium gluconate over 4h) via arterial line in radial or brachial </em></div><div class=\"answer-line\"><em>artery</em></div><div class=\"answer-line\">0 marks if calcium chloride given</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"(12 Marks)\nA 39 year old male presented in acute alcohol withdrawal. In the process of managing his\nwithdrawal, he asbconds and falls to the ground sustaining a head injury. A CT brain is performed and three (3) images are attached below.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) positive findings that are present on the CT images. (4 marks) You are concerned for Left orbital compartment Syndrome."},{"id":"b","label":"Part B","prompt":"List four (4) indications for performing a lateral canthotomy. (4 marks) He experiences a generalised tonic clonic seizure."},{"id":"c","label":"Part C","prompt":"List the four (4) most likely reasons for this to occur. (4 marks) This space is intentionally blank SA/NT TRIAL EXAM SAQ 2023.1\nBOOKLET 3\n(SAQs 19-27)"}],"propPages":["asset:imgd4f8ea16821c65006f","asset:imgce3f076ef3fc422d77","asset:img80498655cc84032e96"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Large haematoma in the left maxillary sinus.</div><div class=\"answer-line\">Prominent haematoma and soft tissue oedema overlying left maxilla.</div><div class=\"answer-line\">Comminuted fracture of the nasal bone.</div><div class=\"answer-line\">Small fracture of the anterior nasal spine.</div><div class=\"answer-line\">Left orbital proptosis.</div><div class=\"answer-line\">Small right parafalcine acute subdural haemorrhage.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">increased IOP causes compromise of retinal blood supply</div><div class=\"answer-line\">visual loss</div><div class=\"answer-line\">RAPD</div><div class=\"answer-line\">Proptosis</div><div class=\"answer-line\">Hard globe on palpation (IOP&gt; 40mmHg)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">TBI</div><div class=\"answer-line\">Alcohol withdrawal seizure</div><div class=\"answer-line\">HypoNa</div><div class=\"answer-line\">Drugs</div><div class=\"answer-line\"><strong>Booklet 3 </strong></div><div class=\"answer-line\"><strong>Answers  </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"(18 marks) A 2-year-old 15 kg child presents in the care of their parent. They have been febrile, and\nunwell for the last 24 hours. They are listless, irritable, and floppy at triage with the\nfollowing observations:\n\nHR\n185 bpm\n\nCR\nsec\n\nRR\nbpm\n\nSpO2 90%\nRA\nFever 39\ndegrees Celsius\n\nGCS\nYour registrar obtains IV access and provides you with a VBG:\n\nPH\n6.90 CO2 mmHg\n\nHCO3\nmmol/L\n\nLactate\nmmol/L\n\nK\n3.3 mmol/L\n\nNa\n138 mmol/L\n\nCl\n103 mmol/L\n\nGlucose\n2.8 mmol/L","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table (6 marks) VBG abnormality- with explanation (6marks)"},{"id":"b","label":"Part B","prompt":"Detail your antibiotic choice and the organism covered in this child. (8 marks) Antibiotic Choice- including dose Treating organism (4 marks) (4 marks) Your registrar completes a sepsis screen and has given the child two 10 mls/kg fluid boluses. The child has the following observations:\n\nHR\n190 bpm\n\nBP\n80/30 mmHg\n\nCR\nsec\n\nSpO2 95%\n• n 3L\n\nRR\nbpm\n\nBSL\n4.5 mmol/L"},{"id":"c","label":"Part C","prompt":"What inotrope would you start in this child? (Include dose.) (2 marks)"},{"id":"d","label":"Part D","prompt":"What are the indications for steroids in paediatric septic shock? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Metabolic acidosis- Lactic acidosis, sepsis</div><div class=\"answer-line\">Respiratory acidosis- Obtunded patient, pneumonia,</div><div class=\"answer-line\">HAGMA-  Lactic acidosis</div><div class=\"answer-line\">Delta ratio 0.75- mixed normal and raised AG- Lactic</div><div class=\"answer-line\">acidosis/diarrhoea/addisons</div><div class=\"answer-line\">Raised lactate- Sepsis</div><div class=\"answer-line\">Hypoglycaemia- Sepsis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Cefotaxime 50mg/kg</td><td>Strep Pneumonia/ N meningitidis/ Hinfluenzae</td></tr><tr><td>Gentamicin 7.5mg/kg</td><td>Ecoli/pseudomonas</td></tr><tr><td>Vancomycin 30mg/kg</td><td>Penicillin resistant pneumococci/MRSA</td></tr><tr><td>Aciclovir 20mg/kg</td><td>HSV</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Adrenaline infusion (0.05mcg-0.1/kg/minute) aiming for improvement in CR, HR.</div><div class=\"answer-line\">Noradrenaline is also acceptable.</div><div class=\"answer-line\">(Only accept mls if they quantify how the infusion was made.)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">History of adrenal insufficiency</div><div class=\"answer-line\">Fluid and vasopressin refractory shock.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"(18 marks)\nA 28-year-old female is brought to your Emergency Department with chest and\nabdominal pain following a high-speed motor vehicle accident. She is 30 weeks pregnant, G1P0, with no other significant past medical history. She has received 500ml\n• f 0.9% NaCl pre-hospital.\nHer vital signs are:\n\nHR\n130 bpm\n\nBP\n85/65 mmHg\n\nRR\nbpm\n\nSpO2 92%\n15 litres O2\n\nTemp 36.1\ndegrees celcius\n\nGCS","parts":[{"id":"a","label":"Part A","prompt":"List three (3) physiological effects of pregnancy on the respiratory system and three (3) effects on the cardiovascular system. (6 marks) Respiratory Cardiovascular (3 marks) (3 marks) Primary survey in this patient reveals reduced breath sounds on the left with associated subcutaneous emphysema. She has lower abdominal tenderness with a seatbelt sign. There is no pelvic or long bone tenderness. GCS remains 15."},{"id":"b","label":"Part B","prompt":"List your next six (6) priorities for management of this patient. (6 marks)"},{"id":"c","label":"Part C","prompt":"List with justification two (2) bedside investigations in this patient. (2 marks)"},{"id":"d","label":"Part D","prompt":"In addition to abdominal tenderness, list four (4) assessment findings that would support a diagnosis of placental abruption in this patient. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Increased tidal volume (30-50%) / increased</td><td>Reduced SVR</td></tr><tr><td colspan=\"2\">minute volume/ increased respiratory rate</td></tr><tr><td>Respiratory alkalosis/ reduced pCO2</td><td>Increased cardiac output (45% by term)</td></tr><tr><td>Reduced FRC (by about 20%)</td><td>Increased heart rate (10-15 bpm)</td></tr><tr><td>Reduced total lung capacity</td><td>Increased stroke volume</td></tr><tr><td>Airway mucosal oedema</td><td>Decreased pulmonary vascular resistance</td></tr><tr><td>Reduced chest wall compliance</td><td>Increased blood volume/ increased plasma</td></tr><tr><td colspan=\"2\">volume (plasma volume increases up to</td></tr><tr><td colspan=\"2\">50%, red cell mass increases by approx. 20%)</td></tr><tr><td>Increased pO2</td><td>Reduced BP- lowest in 2nd trimester,</td></tr><tr><td colspan=\"2\">approaches normal by term</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Insertion of intercostal catheter on left (1-2 spaces higher than in non-pregnant person)</div><div class=\"answer-line\">Activation of Massive Transfusion Pack/ cross match patient</div><div class=\"answer-line\">Manual displacement of uterus</div><div class=\"answer-line\">Appropriate analgesia with dose and route</div><div class=\"answer-line\">Supportive care e.g. maintain normothermia/ normal calcium levels/ prevent acidosis</div><div class=\"answer-line\">Tranexamic acid 1 gram IV followed by infusion</div><div class=\"answer-line\">Identify free fluid in abdomen with FAST; may influence disposition of patient</div><div class=\"answer-line\">Foetal wellbeing- CTG monitoring, obstetric consult, consideration of IM betamethasone</div><div class=\"answer-line\">11.4mg</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ultrasound- identify intra-abdominal free fluid, pneumothorax, pericardial effusion, foetal</div><div class=\"answer-line\">movements etc</div><div class=\"answer-line\">Blood gas- check Hb/ lactate/ calcium etc</div><div class=\"answer-line\">CTG- identify foetal compromise</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Increased uterine tone</div><div class=\"answer-line\">Uterine contractions</div><div class=\"answer-line\">PV loss</div><div class=\"answer-line\">Abnormal foetal heart rate</div><div class=\"answer-line\">Maternal shock</div><div class=\"answer-line\">Severe abdominal pain / uterine tenderness</div><div class=\"answer-line\">Hypo fibrinogenaemia +/- coagulopathy</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"(12 marks) You are working in a regional ED. A 75-year-old man presents after an unwitnessed fall at a residential aged care facility. He has a history of Alzheimer’s dementia, peripheral vascular disease with previous Right below knee amputation and poorly controlled\ntype 2 Diabetes Mellitus. He is complaining of pain in the left leg.\nDuring your examination you note the following finding","parts":[{"id":"a","label":"Part A","prompt":"State the most significant examination findings in the provided image. (3 marks) There is no mention of the observed findings in the medical record form the residential aged care facility, and the patient cannot provide any history to you as he appears delirious on top of his underlying dementia.\nHis observations are as follows:\n\nTemp 38.2\n°C\n\nHR\n124 irregularly irregular bpm\n\nBP\n95/60 mmHg\n\nSaO2 94%\nroom air\n\nRR\nbpm\n\nGCS\n(E4, V4, M5)\n\nBGL\n34.2"},{"id":"b","label":"Part B","prompt":"List the five (5) most important management priorities (5 marks) Your resident has been asked by the consulting team to order some imaging to determine the presence of osteomyelitis."},{"id":"c","label":"Part C","prompt":"Complete the following table regarding the imaging modalities that can be used to investigate for the presence of Osteomyelitis. (4 marks)"}],"propPages":["asset:img37debe3a1a01a04cdc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Necrotic ulcer over the interphalangeal joint of the left great toe</div><div class=\"answer-line\">Erythema over the medial aspect of the left foot, extending from the necrotic toe to the</div><div class=\"answer-line\">medial malleolus</div><div class=\"answer-line\">Purpuric/ischaemic left second toe, ooze</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Resuscitation- A/B- no issue; Fluid bolus- 10ml/kg of hartman’s, targeting systolic over 100</div><div class=\"answer-line\">mmHg</div><div class=\"answer-line\">Supportive care 1. Analgesia 10mcg bolus fentanyl to pt comfort</div><div class=\"answer-line\">Supportive care 2 insulin infusion 50u/50mL .05U/kg/hr – check K</div><div class=\"answer-line\">Specific care: IV antibiotics: Tazocin 4.5gm 8 hourly</div><div class=\"answer-line\">Disposition: Admission for surgical debridement/ source control under vascular surgery</div><div class=\"answer-line\">? Consideration for resus status</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\"><strong>(2 marks) </strong></td></tr><tr><td><strong>X Ray </strong></td><td>cheap</td><td>Not sensitive</td></tr><tr><td>easily available</td><td>Can miss early OM</td><td></td></tr><tr><td colspan=\"3\">if positive no need for further</td></tr><tr><td colspan=\"3\">imaging</td></tr><tr><td><strong>MRI </strong></td><td>Highly sensitive</td><td>Not readily available</td></tr><tr><td colspan=\"3\">expensive</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"(12 marks)\nAn obese 46-year-old male, from interstate, with a background of Haemophilia, presents\nwith atraumatic right hip and knee pain. His range of movement of his hip and knee is unremarkable, with no physical evidence of effusion. He is in moderate pain 5/10 at rest and\n• n movement of his hip 8/10. He complains of shooting pain down his right leg, however\nneurovascularly intact objectively. His observations are:\n\nGCS\n\nPR\n122 bpm\n\nRR\nbpm\n\nSaO2 99%\nRA\n\nBP\n140/70 mmHg\n\nTemp 36.4\ndeg celcius","parts":[{"id":"a","label":"Part A","prompt":"List three (3) differential diagnoses for this patient. (3 marks)"},{"id":"b","label":"Part B","prompt":"Regarding his haemophilia specifically, what important questions should be asked on history? (5 marks)"},{"id":"c","label":"Part C","prompt":"How does Desmopressin work in mild Haemophilia? (2 marks) The patient suddenly becomes hypotensive and groans in pain and becomes hypotensive shocked with altered mentation, therefore further history is unobtainable and there is no collateral."},{"id":"d","label":"Part D","prompt":"When calculating the immediate Haemophilia coagulation factor replacement product that should be given in this case, what two assumptions should be made with justification? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Retroperitoneal bleed / iliopsoas haematoma  (critical to score 3 marks)</div><div class=\"answer-line\">spontaneous hip haemarthrosis- notably patients usually can tell you when they have a joint</div><div class=\"answer-line\">haemarthrosis – pain precedes clinical obvious findings</div><div class=\"answer-line\">cord or nerve root compression – ie sciatica – from – haematoma, infection, disc prolapse.</div><div class=\"answer-line\">No marks as Unlikely MS, knee haemarthrosis, AAA unlikely based on age, however consider</div><div class=\"answer-line\">dissection?</div><div class=\"answer-line\">inguinal hernia too unlikely based on above. No marks for pyelo or renal stone or pancreatitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">What type of haemophilia – type a or b</div><div class=\"answer-line\">Severity</div><div class=\"answer-line\">Prophylaxis (primary prophylaxis)– recombinant or plasma derived – what factor are they on?</div><div class=\"answer-line\">Treatment (secondary prophylaxis)– desmopressin etc</div><div class=\"answer-line\">Antibodies / inhibitors</div><div class=\"answer-line\">Accept - Recent surgery? Past bleeding episodes?</div><div class=\"answer-line\">No marks re who is your haematologist, etc</div><div class=\"answer-line\">c.</div><div class=\"answer-line\">Desmopressin <strong>stimulates the release of stored von willebrand</strong> factor from endothelial</div><div class=\"answer-line\">storage sites, promoting an <strong>increase in factor VIII in the plasma as von Willebrand factor </strong></div><div class=\"answer-line\"><strong>carries factor VIII, hence only for haemophilia A</strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Severity of bleed is severe</strong> – Factor replacement up <strong>to 100%</strong> given assumed massive bleed</div><div class=\"answer-line\">with hypovolaemic shock.</div><div class=\"answer-line\">Patient unable to given history and no collateral and hence we do not know their</div><div class=\"answer-line\">compliance or intrinsic factor level hence <strong>assume intrinsic factor level of 0%</strong></div><div class=\"answer-line\">Accept – based on actual weight and hence use actual weight not ideal body weight given</div><div class=\"answer-line\">obese.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">• Severity of Disease is Classified by Factor Levels</td></tr><tr><td>•</td><td>Normal = 50 – 150% Factor Activity (0.5 – 1.5 IU/mL)</td></tr><tr><td>•</td><td>Mild (60% of Cases) = 5 – 40% Factor Activity (0.05 – 0.4 IU/mL)</td></tr><tr><td>•</td><td>Moderate (15% of Cases) = 1 – 5% Factor Activity (0.01 – 0.05 IU/mL)</td></tr><tr><td>•</td><td>Severe (25% of Cases) = &lt;1% Factor Activity (&lt;0.01 IU/mL)</td></tr><tr><td colspan=\"2\">• In reality as EM Physicians what we need to know for treatment is the patients</td></tr><tr><td colspan=\"2\">Factor Level:</td></tr><tr><td>•</td><td>Option A: The patient knows their factor level</td></tr><tr><td>•</td><td>Option B: Patient Does Not Know their factor level (<strong>If the patient does </strong></td></tr><tr><td colspan=\"2\"><strong>not know their factor level assume 0%</strong>)</td></tr><tr><td colspan=\"2\">• Severity of Bleed</td></tr><tr><td>•</td><td>Mild to Moderate –&gt; Soft Tissue, Muscle, Hemarthrosis, Epistaxis –&gt;</td></tr><tr><td colspan=\"2\">Factor Replacement up to 50% (It is actually more complex than this, but</td></tr><tr><td colspan=\"2\">for sake of simplicity this will work)</td></tr><tr><td>•</td><td>Severe –&gt; CNS, GI, Neck/Throat, Major Trauma (i.e. Life Threatening</td></tr><tr><td colspan=\"2\">Bleeds) –&gt; Factor Replacement up to 100%</td></tr><tr><td colspan=\"2\">• <strong>Putting it all Together (Calculations to Replace Deficient Factor)</strong></td></tr><tr><td>•</td><td><strong>Units of Factor VIII Required = Patients Weight (kg) x 0.5 x (% Activity </strong></td></tr><tr><td colspan=\"2\"><strong>Desired – % Intrinsic Activity)</strong></td></tr><tr><td>•</td><td><strong>Units of Factor IX Required = Patients Weight (kg) x 1.0 x (% Activity </strong></td></tr><tr><td colspan=\"2\"><strong>Desired – % Intrinsic Activity)</strong></td></tr><tr><td colspan=\"2\"><strong>Clinical Take Home Points</strong></td></tr><tr><td>•</td><td>Deficiencies in clotting factors (secondary hemostasis) tend to cause deep bleeds (i.e</td></tr><tr><td colspan=\"2\">hemarthroses, deep muscle) vs superficial bleeds (petechiae, purpura)</td></tr><tr><td>•</td><td>Hemophilia typically has a prolonged aPTT (Intrinsic pathway – Factors VIII &amp; IX) but</td></tr><tr><td colspan=\"2\">normal PT (extrinsic pathway – Factor VII)</td></tr><tr><td>•</td><td>The mainstay of treatment for hemophilia remains replacement of deficient clotting</td></tr><tr><td colspan=\"2\">factors (Always try and use what the patient is on as a first choice)</td></tr><tr><td>•</td><td>If a patient does not know their factor level, assume  it is 0%</td></tr><tr><td>•</td><td>Mild to Moderate bleeds should have their factor replaced up to 50%</td></tr><tr><td>•</td><td>Life threatening/severe bleeds should have their factor replaced up to 100%</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"(12 marks)\nA 40-year-old man is brought to your ED after being found alone on a bridge. He was\nagitated with the paramedics. He is currently being assessed by a Junior Registrar.","parts":[{"id":"a","label":"Part A","prompt":"Excluding age, List FOUR (4) features on history that would suggest a medical cause for this presentation. (4 marks) During the assessment he becomes agitated and requests to leave."},{"id":"b","label":"Part B","prompt":"List the elements required to demonstrate competence. (4 marks) He describes ongoing suicidal ideation, and you determine he requires involuntary treatment."},{"id":"c","label":"Part C","prompt":"Other than age and gender, list FOUR (4) factors would increase his risk of completing suicide. (4 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Delirium: Fluctuating changes to mental state over hours to days; abrupt onset</div><div class=\"answer-line\">Cognitive changes – Disorientation, memory loss/deficit, language disturbance</div><div class=\"answer-line\">Perception – Visual hallucinations, illusions</div><div class=\"answer-line\">Drug or alcohol use/Substance abuse or history of overdose</div><div class=\"answer-line\">Recent or new medical problems</div><div class=\"answer-line\">Neurological complaints – Weakness, ataxia, tremor</div><div class=\"answer-line\">Historical features: Fever, head trauma, immunocompromise (esp. HIV)</div><div class=\"answer-line\">Polypharmacy or new medication</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Maintain and communicate a choice</div><div class=\"answer-line\">Understand the relevant information</div><div class=\"answer-line\">Appreciate the situation and its consequences</div><div class=\"answer-line\">Manipulate the information in a rational fashion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">High Risk Factors associated with Suicide</div><div class=\"answer-line\">• (Male)</div><div class=\"answer-line\">• Marital status – Recently separated, divorced, widowed; recent relationship</div><div class=\"answer-line\">breakdown</div><div class=\"answer-line\">• Employment – Recent unemployment/retired</div><div class=\"answer-line\">• Medical – Chronic illness, chronic pain, epilepsy</div><div class=\"answer-line\">• Psychiatric – Bipolar, depression, schizophrenia, panic disorder, antisocial or conduct</div><div class=\"answer-line\">disorder, Substance abuse</div><div class=\"answer-line\">• Mood – Feeling helpless/hopeless, Few reasons for living, feeling life is not worth</div><div class=\"answer-line\">living</div><div class=\"answer-line\">• Social – Chaotic/conflictual family, Family history of suicide, developmental trauma,</div><div class=\"answer-line\">Indigenous, refugee from conflict area, developmental trauma</div><div class=\"answer-line\">• Suicidal ideation</div><div class=\"answer-line\">o Intense, frequent, prolonged or pervasive.</div><div class=\"answer-line\">▪ No remorse; continued wish to die</div><div class=\"answer-line\">o Previous suicide attempt, specific suicide plan</div><div class=\"answer-line\">o Suicide lethality – Violent, lethal and available method</div><div class=\"answer-line\">o Planned, active preparation, realistic plan</div><div class=\"answer-line\">o Act performed in isolation or concealed from others</div><div class=\"answer-line\">o Final acts (wills, insurance, giving away property)</div><div class=\"answer-line\">o Coping skills – Unwilling to seek help</div><div class=\"answer-line\">o Precipitant that can recur; acute precipitant not resolved</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"(12 marks)\nA 12-month-old has been found locked inside a vehicle on a hot day.\nShe was removed from the vehicle by emergency services and has been brought to your emergency department with a reduced level of consciousness. The parents have not yet been located.\nHer vital signs on arrival are:\n\nHR\n185 bpm\n\nBP\n60/40 mmHg\n\nRR\nbpm\n\nSaO2 93%\nRA\n\nTemp 41\n°C\n\nGCS","parts":[{"id":"a","label":"Part A","prompt":"List four (4) methods for reducing the temperature in this patient. (4 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table with SIX potential complications of heat stroke, and an investigation which would identify each complication. (6 marks) Comnplication WITH investigation (6 marks)"},{"id":"c","label":"Part C","prompt":"List TWO services that you will refer to for assistance with ongoing care of this patient. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Remove clothing and blankets</div><div class=\"answer-line\">Evaporative cooling - fans, misting, damp flannels</div><div class=\"answer-line\">Cool IV fluids</div><div class=\"answer-line\">Ice packs to axilla and groin</div><div class=\"answer-line\">Midazolam can be used to control shivering during cooling</div><div class=\"answer-line\"><em>No marks for paracetamol in the context of environmental overheating.  </em></div><div class=\"answer-line\"><em>There is no role for invasive cooling. I expect some candidates to list treatment options for </em></div><div class=\"answer-line\"><em>HYPOthermia, but the invasive methods used for rewarming are not used for cooling. </em></div><div class=\"answer-line\"><em>No marks for ice bath (ice bath is listed as a treatment in some adult heat stroke guidelines, </em></div><div class=\"answer-line\"><em>but not recommended in children - lowers temperature quickly but is less well tolerated than </em></div><div class=\"answer-line\"><em>other methods). </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>COMPLICATION</td><td>INVESTIGATION</td></tr><tr><td>Electrolyte abnormalities</td><td>Blood gas, electrolytes, ECG</td></tr><tr><td>Hypo / hyperglycemia</td><td>Blood sugar level</td></tr><tr><td>Lactic acidosis</td><td>Blood gas</td></tr><tr><td>Disseminated intravascular coagulation</td><td>Coagulation studies</td></tr><tr><td>Rhabdomyolysis</td><td>CK</td></tr><tr><td colspan=\"2\">Urinalysis for myoglobinuria</td></tr><tr><td>Acute hepatic injury</td><td>LFTs (transaminases)</td></tr><tr><td>Renal failure</td><td>Creatinine, urinalysis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">PICU</div><div class=\"answer-line\">Pediatric inpatient team</div><div class=\"answer-line\">Child Protection Services (critical mark)</div><div class=\"answer-line\"><em>Also correct answers: social work, police to locate parents </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"(13 marks) A 68-year-old man falls at home sustaining a facial injury. He has a bruise on his hands from landing and has C spine tenderness. He is immobilized appropriately on arrival.","parts":[{"id":"a","label":"Part A","prompt":"Describe the anatomical mechanism that results in Central Cord Syndrome and describe the pathologically effected anatomy. (2 marks)"},{"id":"b","label":"Part B","prompt":"Describe in broad terms how central cord syndrome presents clinically. (3 marks) In the ED the patient is found be profoundly hypotensive with a temperature of 33. You suspect he has neurogenic shock."},{"id":"c","label":"Part C","prompt":"In the context of a multi-injured trauma patient, state the conditions that must be met before the diagnosis of neurogenic shock is made. (4) The patient suffered a permanent T3 level spinal cord injury, and a year later presented with sudden onset severe headache, flushing of the face and pallor in their lower limbs. He is profoundly sweaty and have a BP of 220 / 108. You suspect autonomic dysreflexia syndrome."},{"id":"d","label":"Part D","prompt":"Give four (4) causes involving different organ systems that could be causing this syndrome. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hyperextension of neck or Ligamentum flavum, buckles into cord (1)</div><div class=\"answer-line\">Concussion or contusion of central grey matter in most central portions of pyramidal and</div><div class=\"answer-line\">spinothalamic tracts (1)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">arms more severely affected than legs (1)</div><div class=\"answer-line\">motor affected &gt; sensory  –  (1)</div><div class=\"answer-line\">some patients only have sacral sparing (1)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patient must be flaccid and areflexic</div><div class=\"answer-line\">Must have absent reflex tachycardia</div><div class=\"answer-line\">Must have absent peripheral vasoconstriction</div><div class=\"answer-line\">Must have excluded other causes of shock including haemorrhagic shock, tamponade and</div><div class=\"answer-line\">tension pneumothorax</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bladder: Distended or hyperactive bladder, urinary tract infection, bladder or kidney</div><div class=\"answer-line\">stones, urological procedure or even inserting a catheter.</div><div class=\"answer-line\">Bowel: Constipation, faecal impaction, rectosigmoid gaseous distension, rectal irritation</div><div class=\"answer-line\">(e.g. enema or manual evacuation), haemorrhoids.</div><div class=\"answer-line\">Skin: Other: Ingrown toenail, burns, pressure area, tight clothing.</div><div class=\"answer-line\">Other: Any irritating stimulus, including fracture, epididymoorchitis, distended stomach,</div><div class=\"answer-line\">sexual intercourse, labour or severe menstrual cramping.</div><div class=\"answer-line\">autonomic dysreflexiamay be caused iatrogenically by staff clamping a catheter for a</div><div class=\"answer-line\">procedure such as a bladder ultrasound or kinking catheter by accident in operating theatre</div><div class=\"answer-line\">during a surgical procedure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"(12 marks) A 56-year-old male presents with acute confusion and visibly jaundiced after returning two weeks ago from an international conference. He lives alone at home. He has no background medical history and has no mental health or drug and alcohol related history.\nHis observations are:\n\nGCS\nE4 V3 M5\n\nPR\n122 bpm\n\nRR\nbpm\n\nSaO2 96%\nRA\n\nBP\n110/70 mmHg\n\nTemp 35.9\ndeg celcius","parts":[{"id":"a","label":"Part A","prompt":"What six (6) complications might be expected in this patient? (6 marks)"},{"id":"b","label":"Part B","prompt":"Specifically, regarding investigation of his hepatic encephalopathy what blood test may be of use and state the caveat in performing this test? (1 mark)"},{"id":"c","label":"Part C","prompt":"How is this test useful? (1 mark)"},{"id":"d","label":"Part D","prompt":"Regarding his hepatic encephalopathy, what medication treatment options may\n\nbe used? (2 marks)"},{"id":"e","label":"Part E","prompt":"List the disposition of this patient. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cerebral oedema +- herniation – include seizures and coma here. – Critical</div><div class=\"answer-line\">Coagulopathy</div><div class=\"answer-line\">GI bleed</div><div class=\"answer-line\">Sepsis</div><div class=\"answer-line\">Renal failure</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Electrolyte abnormalities</div><div class=\"answer-line\">Respiratory failure- ARDS, intrapulmonary shunts.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ammonia level – must be sent quickly or stored on ice -otherwise will be inaccurate. No</div><div class=\"answer-line\">half marks.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Levels may correlate with encephalopathy grade/severity and trending can be useful to</div><div class=\"answer-line\">track response to treatment and prognostication, including able to predict a likelihood of</div><div class=\"answer-line\">cerebral herniation and death.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Lactulose – ammonia elimination</div><div class=\"answer-line\">Rifaximin/Metronidazole – alters gut flora to decrease ammonia production.</div><div class=\"answer-line\">Candidates may list hypertonic saline, mannitol, or check BGL and treat BGL, MARS etc, all wrong in</div><div class=\"answer-line\">context of stem at this stage.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Management must be in ICU</div><div class=\"answer-line\">Early discussion with liver transplant unit</div><div class=\"answer-line\">Discussion with family  -high mortality</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"(12 marks) You are performing a POCUS lung scan on a 65-year-old man with acute shortness of breath. He has a history of COPD and CCF. He has been in your ED for over 12 hours when he became more acutely dyspnoeic. Image A was obtained on arrival in the R upper zone of the chest Image B was obtained in the same zone when his clinical state deteriorated Image A Image B","parts":[{"id":"a","label":"Part A","prompt":"Identify the main features labelled 1 to 4 in Images A and B. (4 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) points that define feature 4 in question 1. (4 marks)"},{"id":"c","label":"Part C","prompt":"List four (4) points that indicate that feature 4 is highly indicative of heart failure. (4 marks)"}],"propPages":["asset:imgd5282ab0181695e53c","asset:img48255bc9bbce6a536d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>1</td><td>Pleural line</td></tr><tr><td>2</td><td>Rib shadow</td></tr><tr><td>3</td><td>A line</td></tr><tr><td>4</td><td>B line</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Extend from the pleura</div><div class=\"answer-line\">Move with the pleura</div><div class=\"answer-line\">Extend through the depth of the field</div><div class=\"answer-line\">Erase A lines (feature 3)</div><div class=\"answer-line\">hyperechoic and well defined</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Greater than or equal to 3 B lines per FIELD Of VIEW or &gt; 2 if the greater than</div><div class=\"answer-line\">or equal to symbol is not available</div><div class=\"answer-line\">Bilateral</div><div class=\"answer-line\">Symmetrical              “diffuse” and “usually symmetrical”</div><div class=\"answer-line\">Coalesce with increasing severity (of pulmonary oedema)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
